import java.util.Scanner;

public class cf723b {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        int length = input.nextInt();
        String document = input.next();
        int maxWord = 0;
        int parenthesisWords = 0;
        boolean inParen = false;
        boolean lastLetter = false;
        int currentCount = 0;

        for (int i = 0; i < document.length(); i++) {
            char ch = document.charAt(i);
            if (ch == '(') {
                inParen = true;
                lastLetter = false;
                currentCount = 0;
            } else if (ch == ')') {
                inParen = false;
                lastLetter = false;
                currentCount = 0;
            } else if (Character.isLetter(ch)) {
                if (inParen && !lastLetter) {
                    parenthesisWords++;
                } else if (!inParen) {
                    currentCount++;
                    maxWord = Math.max(maxWord, currentCount);
                }
                lastLetter = true;
            } else {
                lastLetter = false;
                currentCount = 0;
            }
        }
        System.out.print(maxWord + " " + parenthesisWords);
        input.close();
    }
}
